 signals={'organization_any_year_2011_2025':e.gt(0).any(axis=1).to_numpy(),'organization_2025':e.econ_native_2025_legal_entities.gt(0).to_numpy(),'consumer_legal_2025':s.legal_native_function_diversity.gt(0).to_numpy(),'consumer_legal_conditional_2025':s.legal_conditional_function_diversity.gt(0).to_numpy(),'places_baseline_snapshot':s.physical_baseline_function_diversity.gt(0).to_numpy(),'places_conditional_snapshot':s.physical_conditional_function_diversity.gt(0).to_numpy(),'wb_strict_all_types_snapshot':wb.wb_strict_all_types_locations.gt(0).to_numpy(),'wb_strict_focus_types_snapshot':s.wb_strict_focus_published_locations.gt(0).to_numpy(),'municipal_agricultural_series':ag.agri_municipality_series_matched.to_numpy(bool),'municipal_agricultural_valid_profile_2021':ag.agri_profile2021_covered.to_numpy(bool),'baseline_any_function':s.baseline_function_diversity.gt(0).to_numpy(),'baseline_multiple_functions':s.baseline_function_diversity.ge(2).to_numpy(),'conditional_any_function':s.conditional_function_diversity.gt(0).to_numpy(),'conditional_multiple_functions':s.conditional_function_diversity.ge(2).to_numpy()}
 size=np.select([~np.isfinite(pop),pop==0,pop<100,pop<500,pop<2000,pop<10000],['unknown','0','1-99','100-499','500-1999','2000-9999'],default='10000+');regions=axis.region.to_numpy()
