 try:pd.testing.assert_frame_equal(original,relations,check_dtype=False,check_exact=True);equal=True
 except AssertionError:equal=False
 ck('all_original_138_documentary_source_rows',equal and len(original)==138);ck('all_79_unique_relations',len(original.drop_duplicates(['origin_uid','destination_uid','function_group']))==79);ck('75_documented_origins',original.origin_uid.nunique()==75);ck('17_documented_destinations',original.destination_uid.nunique()==17);ck('documentary_axis_full_once',len(f)==142570 and f.index.is_unique);ck('not_actual_trip_measurement',not original.actual_flow_observed.any() and f.documented_actual_trip_count.isna().all())
 for c,expected in [('documented_external_service_assertions',original.groupby('destination_uid').size()),('documented_external_origin_UIDs',original.groupby('destination_uid').origin_uid.nunique()),('documented_external_function_diversity',original.groupby('destination_uid').function_group.nunique())]:ck('all_UID_'+c,np.array_equal(expected.reindex(ids,fill_value=0).to_numpy(),f[c].to_numpy()))
 pc=read(N/'places/places_settlement_features.parquet',columns=['id']+[f'places_{mode}_{g}_count' for mode in ['baseline','conditional'] for g in ['school','preschool','other_education','hospital','healthcare']]).set_index('id');ec=read(N/'economy/economy_features.parquet',columns=['id','econ_native_2025_education85_legal_entities','econ_native_2025_health86_legal_entities']).set_index('id');control=read(N/'report_tables/documentary_control.csv').set_index('function');doc_summary=[]
 for fn,categories,legal in [('education',['school','preschool','other_education'],'education85'),('health',['hospital','healthcare'],'health86')]:
  providers=original.loc[original.function_group.eq(fn),'destination_uid'].unique();count={mode:int(pc.loc[providers,[f'places_{mode}_{g}_count' for g in categories]].sum(axis=1).gt(0).sum()) for mode in ['baseline','conditional']};legalpositive=int(ec.loc[providers,f'econ_native_2025_{legal}_legal_entities'].gt(0).sum());r=control.loc[fn];ck('documentary_control_'+fn,r.documented_provider_UID==len(providers) and r.baseline_POI_positive_UID==count['baseline'] and r.conditional_POI_positive_UID==count['conditional'] and r.native_legal_positive_UID_2025==legalpositive);doc_summary.append({'function':fn,'providers':len(providers),'POI_baseline':count['baseline'],'POI_conditional':count['conditional'],'RFSD_native2025':legalpositive})
 # All 30 WB conditional raw fields must match both published downstream layers.
 wr=read(N/'services/wb_name_relaxed_features.parquet');cols=wr.columns.tolist();master=read(N/'core/feature_master.parquet',columns=cols).set_index('id').reindex(wr.id);screen=read(N/'screening/support_point_profiles.parquet',columns=cols).set_index('id').reindex(wr.id);wr=wr.set_index('id')
 for c in wr:ck('WB_relaxed_all_UID_master_screening_'+c,np.array_equal(wr[c],master[c]) and np.array_equal(wr[c],screen[c]))
 ck('all_inputs_stable',all(sha(Path(p))==v for p,v in used.items()));result={'status':'PASS' if all(x['pass'] for x in checks) else 'FAIL','checks':checks,'documentary_diagnostic':doc_summary,'input_SHA256':used,'code_SHA256':sha(Path(__file__)),'meaning':'Descriptive point/population coverage and a selected nonblind documentary diagnostic. Population weights are residents of source-positive reference points, not service users; no national accuracy or policy effectiveness estimate.'};(O/'AUDIT.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print(result['status'],len(checks),'checks',doc_summary,flush=True);assert all(x['pass'] for x in checks)
